#endif
//global.c, 源文件真正的定义
#include "global.h"
int g_count = 0; // 唯一定义
void inc(void) {
g_count++;
}
//main.c, 使用者文件只 include 头文件
#include
#include "global.h"
int main(void) {
inc();
printf("%d\n", g_count);
return 0;
}
