int append(FILE *source, FILE *dest)
{
size_t bytes_read, bytes_written;
char temp[BUFSIZE];
while ((bytes_read = fread(temp, 1, BUFSIZE, source)) > 0)
{
bytes_written = fwrite(temp, 1, bytes_read, dest);
if (bytes_written != bytes_read)
return -2; // 写错误
}
// fread == 0 有两种可能：EOF（正常）,出错（异常）, 必须用 ferror 区分
if (ferror(source))
return -1; // 读错误
// 即使fwrite都成功了, 数据可能还在缓冲区里
if (fflush(dest) != 0)
return -3; // flush 失败
return 0;
}
char *s_gets(char *st, int n)
{
char *ret_val;
char *find;
// fget最多读n-1个,第n位补\0
ret_val = fgets(st, n, stdin);
if (ret_val)
{
find = strchr(st, '\n');
if (find)
*find = '\0';
// 例如n=5,输入abc回车
// fget结果为abc\n\0
// st结果abc\n
// 找到\n替为\0
else
// 输入abcde回车
// fget结果abcd\0
// e\n被消耗
while (getchar() != '\n')
continue;
}
return ret_val;
}
