移位运算符针对2的幂提供快速有效的乘法和除法, 类似于在十进制中移动小数点来乘以或除以10
number << n; // number乘以2的n次幂
number >> n; // 如果number为非负，则用number除以2的n次幂
移位运算符还可用于从较大单元中提取一些位
例如用一个 unsigned long类型的值表示颜色值，低阶位字节储存红色的强度，下一个字 节储存绿色的强度，第 3 个字节储存蓝色的强度。随后你希望把每种颜色的 强度分别储存在3个不同的unsigned char类型的变量中。
#define BYTE_MASK 0xff
unsigned long color = 0x002a162f;
unsigned char blue, green, red;
red = color & BYTE_MASK;
green = (color >> 8) & BYTE_MASK;
blue = (color >> 16) & BYTE_MASK;
/* binbit.c -- 使用位操作显示二进制 */
#include
#include
// 提供 CHAR_BIT 的定义，CHAR_BIT 表示每字节 的位数, c没有要求1字节具体多少位
char *itobs(int, char *);
void show_bstr(const char *);
int invert_end(int num, int bits);
int main(void)
{
char bin_str[CHAR_BIT * sizeof(int) + 1];
int number;
puts("Enter integers and see them in binary.");
puts("Non-numeric input terminates program.");
while (scanf("%d", &number) == 1)
{
itobs(number, bin_str);
printf("%d is ", number);
show_bstr(bin_str);
putchar('\n');
number = invert_end(number, 4);
printf("Inverting the last 4 bits gives\n");
show_bstr(itobs(number, bin_str));
putchar('\n');
}
puts("Bye!");
return 0;
}
char *itobs(int n, char *ps)
{
int i;
const static int size = CHAR_BIT * sizeof(int);
for (i = size - 1; i >= 0; i--, n >>= 1)
ps[i] = (n & 1) + '0';
// 把数字 0/1 转换成字符 '0'/'1'
// n & 1 掩码结果只能是整数0或1
// '0'字符的ASCII值是48,'1'是49
// ps[i]最终字符落在0+48,或1+48, 即'0'或'1'
ps[size] = '\0';
return ps;
}
/*4位一组显示二进制字符串 */
void show_bstr(const char *str)
{
int i = 0;
while (str[i]) /* 不是一个空字符 */
{
putchar(str[i]);
if (++i % 4 == 0 && str[i])
putchar(' ');
}
}
// 切换一个值中的后 n 位
int invert_end(int num, int bits)
{
int mask = 0;
int bitval = 1;
while (bits-- > 0)
{
mask |= bitval;
bitval <<= 1;
}
return num ^ mask;
// 先构造一个“低 bits 位全为 1 的掩码 mask”，再用 XOR 把 num 的这些位翻转
}
操控位的第2种方法是位字段（bit field）。位字段是一个signed int或 unsigned int类型变量中的一组相邻的位（C99和C11新增了_Bool类型的位字 段）。位字段通过一个结构声明来建立，该结构声明为每个字段提供标签， 并确定该字段的宽度。
要确保所赋的值不超出字段可容纳的范围, 位宽为1时只能容纳1或0
struct {
unsigned int field1 : 1;
unsigned int : 2; // 两个“空位”, 跳过 2 个 bit
unsigned int field2 : 1;
unsigned int : 0; // 强制对齐到下一个存储单元
unsigned int field3 : 1;
} stuff;
其中 unsigned int : 0;
结束 bit-field1 分配，剩余空间不再使用，直接跳到下一个 unsigned int 边界, 后面的 field3 会重新开始一个新的 int 存储单元
bit-field 用于按位压缩存储，但其内存布局是实现相关的，因此不可用于跨平台数据交换
