预处理器
预处理器指令, 行末注释, 现代代码用 //，追求兼容性用 /* */
C 预处理器流程是：先去注释 → 再处理预处理指令 → 再宏展开
/* preproc.c -- 简单的预处理示例 */
#include
#define TWO 2 /* 可以使用注释 */
#define OW "Consistency is the last refuge of the unimagina\
tive.- Oscar Wilde" /* 反斜杠把该定义延续到下一行 */
#define FOUR TWO*TWO
#define PX printf("X is %d.\n", x)
#define FMT "X is %d.\n"
/* 预处理器指令 宏 替换体(宏展开) */
int main(void){
int x = TWO;
PX;
x = FOUR;
printf(FMT, x);
printf("%s\n", OW);
printf("TWO: OW\n");
return 0;
}
预处理器不做计算，不对表达式求值，它只进行替换
编译器在编译期对所有的常量表达式（只包含常量的表达式）求值，所以预处理器不会进行实际的乘法运算，这一过程在编译时进行 x = FOUR;
变成：
x = TWO*TWO;
再变成：
x = 2*2
宏展开到此处为止, 不会继续变成x = 4;
如果要多次使用某个冗长的字符串，FMT这种方法比较方便
另外，也可以用下面的方法：
const char * fmt = "X is %d.\n";
然后可以把fmt作为printf()的格式字符串
类函数宏
#define SQUARE(X) X*X
在程序中可以这样用：
z = SQUARE(2);
/* mac_arg.c -- 带参数的宏 */
#include
#define SQUARE(X) X*X
#define PR(X) printf("The result is %d.\n", X)
int main(void){
int x = 5;
int z;
printf("x = %d\n", x); // 5
z = SQUARE(x);
printf("Evaluating SQUARE(x): ");
PR(z); // 25
z = SQUARE(2);
printf("Evaluating SQUARE(2): ");
PR(z); // 4
printf("Evaluating SQUARE(x+2): ");
PR(SQUARE(x + 2)); // x*x变成了x+2*x+2, 5+2*5+2, 改#define SQUARE(x) (x)*(x)
printf("Evaluating 100/SQUARE(2): ");
PR(100 / SQUARE(2)); // 变成了100/(2)*(2), 再改#define SQUARE(x) ((x)*(x))
// 使用足够多的圆括号来确保运算和结合的正确顺序
printf("x is %d.\n", x);
printf("Evaluating SQUARE(++x): ");
PR(SQUARE(++x)); // ++x*++x = 6*7, 不要在宏中使用递增或递减运算符
printf("After incrementing, x is %x.\n", x); // 7
return 0;
}
