#pragma 给编译器特殊提示
设置对齐
#pragma pack(1) // 设置为 1 字节对齐
struct A { ... };
#pragma pack() // 恢复默认对齐(不一定是之前的对齐值), 不推荐
#pragma pack(push, 1) // 把当前对齐方式压入栈, 然后设置为 1 字节对齐
