Binary Search Tree
typedef struct Node {
int key;
struct Node *left;
struct Node *right;
} Node;
// 递归
Node* search(Node* root, int key)
{
if (root == NULL)
return NULL;
if (key == root->key)
return root;
if (key < root->key)
return search(root->left, key);
return search(root->right, key);
}
// 非递归
Node* search(Node* root, int key)
{
while (root)
{
if (key == root->key)
return root;
if (key < root->key)
root = root->left;
else
root = root->right;
}
return NULL;
}
